def seed_initial_content(apps, schema_editor):
    """Load the published CMS snapshot without replaying obsolete transformations."""
    source = Path(__file__).with_name("0001_initial_data.json")
    records = json.loads(source.read_text(encoding="utf-8"))
    alias = schema_editor.connection.alias
    seeded_models = []

    for record in records:
        app_label, model_name = record["model"].split(".", 1)
        model = apps.get_model(app_label, model_name)
        values = {}
        for name, value in record["fields"].items():
            field = model._meta.get_field(name)
            values[field.attname if field.many_to_one else name] = value
        model.objects.using(alias).create(pk=record["pk"], **values)
        if model not in seeded_models:
            seeded_models.append(model)

    statements = schema_editor.connection.ops.sequence_reset_sql(no_style(), seeded_models)
    with schema_editor.connection.cursor() as cursor:
        for statement in statements:
            cursor.execute(statement)


